with page (id) as ( select psm1_0.product_id from product_stat psm1_0 where psm1_0.deleted_at is null order by psm1_0.like_count desc,psm1_0.product_id desc offset 4950 rows fetch first 50 rows only) select pm1_0.id,pm1_0.name,pm1_0.price,bm1_0.id,bm1_0.name,psm2_0.like_count from page pg1_0 join product pm1_0 on pm1_0.id=pg1_0.id join brand bm1_0 on bm1_0.id=pm1_0.brand_id join product_stat psm2_0 on psm2_0.product_id=pm1_0.id order by psm2_0.like_count desc,psm2_0.product_id desc
